{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{% set so = frappe.get_doc("Sales Order", doc.sales_order) %}{% set src = frappe.get_doc("Delivery Note", doc.delivery_note) if doc.delivery_note else so %}{{ header("PACKING LIST", "قائمة التعبئة", doc.name, doc.etd or frappe.utils.nowdate(), doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Consignee · المرسل إليه</div><b>{{ doc.customer_name }}</b><br>{{ so.address_display or "" }}</div><div><div class="hs-h4">Shipment · الشحنة</div>Order: {{ doc.sales_order }} · Buyer PO {{ so.po_no or "—" }}<br>Incoterm: {{ doc.incoterm or "—" }} {{ doc.named_place or "" }}<br>{{ doc.mode }}: {{ doc.port_of_loading or "—" }} → {{ doc.destination or "—" }}<br>B/L / AWB / CMR: {{ doc.bl_awb_cmr or "to follow" }}{% if doc.declaration_no %}<br>Declaration: {{ doc.declaration_no }}{% endif %}</div></div>
<table class="hs-t"><thead><tr><th>#</th><th>Description · الوصف</th><th>HS code</th><th>Origin</th><th class="n">Qty</th><th>Unit</th></tr></thead><tbody>{% for i in src.items %}<tr><td>{{ loop.index }}</td><td>{{ i.item_name }}{% set ar = hs_arabic_name(i.item_code) %}{% if ar %}<span class="ar-sub">{{ ar }}</span>{% endif %}</td><td>{{ frappe.db.get_value("Item", i.item_code, "customs_tariff_number") or "—" }}</td><td>{{ frappe.db.get_value("Item", i.item_code, "country_of_origin") or "—" }}</td><td class="n">{{ i.get_formatted("qty") }}</td><td>{{ i.uom }}</td></tr>{% endfor %}</tbody></table>
<div class="hs-note">We certify that the goods above are packed as listed and match the commercial invoice.</div>
{{ signs("Shipper — " ~ doc.company, "Received by carrier") }}
</div>
